/**
 * The monitor's configuration (generated by `wp2emdash monitor build` into src/monitor-config.ts: URLs and alert
 * addresses only, never a token) and the Worker's environment (secrets set with `wrangler secret put`).
 */

export interface MonitorSite {
	/** Stable id: the site's slug, or the extra URL's id / host. Key of its state. */
	id: string;
	/** The address checked: home page, https. */
	url: string;
	/** Optional word or phrase the home page must contain (case-insensitive). */
	keyword?: string;
	/** Registrable domain for the domain-expiry lookup (default: derived from the host). */
	domain?: string;
	/** Certificate + domain expiry checks (default true; always off for *.workers.dev). */
	expiry?: boolean;
	/** "site": generated from sites/<slug>/; "extra": monitor.config.json extraUrls. */
	source?: "site" | "extra";
}

export interface MonitorConfig {
	version: 1;
	sites: MonitorSite[];
	/** Agency alert recipients. */
	alertTo: string[];
	/** Sender, e.g. "Site monitor <monitor@agency.example>" (a sender verified at the email provider). */
	from?: string;
	/** brevo (default) · resend · postmark · sendgrid · mailgun — the providers @wp2emdash/forms delivers through. */
	emailProvider?: string;
	/** Telegram chat id (not a secret; the bot token is the TELEGRAM_BOT_TOKEN secret). */
	telegramChatId?: string;
	/** Home page time limit per check. */
	timeoutMs: number;
	/** Warn when a certificate or domain expires within this many days. */
	expiryWarnDays: number;
	/** At most this many alert messages per UTC day (all channels count as one message). */
	maxAlertsPerDay: number;
	/** Weekly "all good" summary, Mondays 08:00 UTC. Off by default. */
	weeklySummary: boolean;
	/** Shown in subjects and on the status page, e.g. the agency name. */
	label?: string;
}

/** The subset of Workers KV the monitor uses. */
export interface KvStore {
	get(key: string): Promise<string | null>;
	put(key: string, value: string): Promise<void>;
}

export interface MonitorEnv {
	MONITOR_KV: KvStore;
	/** Email provider API key (Brevo by default). Secret. */
	EMAIL_API_KEY?: string;
	MAILGUN_REGION?: string;
	/** Telegram bot token. Secret. */
	TELEGRAM_BOT_TOKEN?: string;
	/** Slack incoming webhook URL. Secret. */
	SLACK_WEBHOOK_URL?: string;
	/** Token for the status page (?token=…). Unset: no status page (404). Secret. */
	STATUS_TOKEN?: string;
	/** Optional dead-man's switch: GET once per tick (e.g. a healthchecks.io ping URL). Secret. */
	HEARTBEAT_URL?: string;
	/** Optional Cert Spotter API key (more than the anonymous hourly quota). Secret. */
	CERTSPOTTER_API_KEY?: string;
}

export type Fetch = (url: string, init?: RequestInit) => Promise<Response>;
